
import type { ReturnPolicyScopeInput } from './ReturnPolicyScopeInput.js';
import type { ReturnRestockingFeePolicyInput } from './ReturnRestockingFeePolicyInput.js';
import type { ReturnShippingPolicyInput } from './ReturnShippingPolicyInput.js';
import type { ReturnWindowInput } from './ReturnWindowInput.js';

export type ReturnPolicyRevisionInput = { "allowed_resolution_types": Array<"refund" | "exchange" | "replacement" | "no_monetary_action">; "approval_mode": "automatic" | "manual"; "automatic_resolution_type"?: "refund" | "exchange" | "replacement" | "no_monetary_action"; "completion_mode"?: "manual" | "automatic"; /** RFC3339 timestamp. Format: date-time. */ "created_at": string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "effective_at"?: string | globalThis.Date; "eligibility_result": "eligible" | "ineligible" | "review_required"; "ineligibility_reason"?: "final_sale" | "product_excluded" | "category_excluded" | "market_restricted" | "channel_restricted" | "outside_return_window" | "other"; "is_inspection_required"?: boolean; "is_merchandise_return_required": boolean; /** Format: int32. */ "priority": number; /** Controls verified merchandise after receipt. automatic creates a successful sellable disposition at the receiving location. For tracked merchandise, it also creates an inventory receipt and movement. Untracked merchandise has no inventory effect. If the Return line requires inspection, creation waits for an accepted inspection. manual leaves inventory unchanged until an explicit disposition succeeds. When omitted, the value defaults to automatic. */ "receipt_disposition_mode": "automatic" | "manual"; "receiving_location_id"?: string; "refund_timing"?: "after_approval" | "after_handoff" | "after_receipt" | "after_inspection" | "manual"; "resolution_mode"?: "automatic" | "manual"; "resolution_selection_mode"?: "policy_default" | "buyer_requested"; "restocking_fee"?: ReturnRestockingFeePolicyInput; "return_policy_id": string; "return_policy_revision_id": string; "return_shipping"?: ReturnShippingPolicyInput; "return_window"?: ReturnWindowInput; "scope": ReturnPolicyScopeInput; };
